const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const titles={dashboard:'Farm overview',farms:'My farms',recommend:'Crop recommendation',diagnose:'Crop health check',weather:'Weather update',market:'Market prices',assistant:'AI farming assistant',planner:'Operations planner',decision:'Autonomous farm decision engine',impact:'Water & profit',fieldmap:'Field health map',shops:'Nearby agricultural shops',recovery:'Crop recovery tracker',soilhealth:'Soil health advisor',yieldrisk:'Yield & risk simulator',calendar:'Smart farm calendar',schemes:'Government schemes & expert help'};
const crops=['Wheat','Rice','Mustard','Maize','Chickpea','Cotton','Tomato'];
const prices=[['Wheat',2550,'Stable'],['Rice / Paddy',2320,'Rising'],['Mustard',6100,'Stable'],['Maize',2250,'Falling'],['Chickpea',5600,'Stable'],['Cotton',7200,'Rising'],['Tomato',1800,'Volatile']];
const seed=[{id:1,name:'Demo Farm',location:'Demo Village, Sonipat, Haryana',village:'Demo Village',district:'Sonipat',state:'Haryana',crop:'Wheat',area_acres:4,soil_type:'Loamy',soil_ph:6.7,moisture:'medium',land_status:'owner',farmer_category:'small-marginal',irrigation:'tubewell',scheme_need:'general'}];
let farms=read('agri-farms',seed), activities=read('agri-activities',[]), currentWeather=null;
function read(k,d){try{return JSON.parse(localStorage.getItem(k))??d}catch{return d}}
function save(){localStorage.setItem('agri-farms',JSON.stringify(farms));localStorage.setItem('agri-activities',JSON.stringify(activities))}
async function backendPost(path,payload){try{const r=await fetch(path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});if(!r.ok)throw new Error('API '+r.status);return await r.json()}catch(err){console.info('Backend not connected; browser-local copy retained.',err.message);return null}}
async function backendPut(path,payload){try{const r=await fetch(path,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});if(!r.ok)throw new Error('API '+r.status);return await r.json()}catch(err){console.info('Backend sync unavailable; browser-local copy retained.',err.message);return null}}
function esc(s=''){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function toast(msg){const t=$('#toast');if(!t)return;t.textContent=msg;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2400)}
function go(view){$$('.view').forEach(v=>v.classList.toggle('active',v.id===view));$$('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('#page-title').textContent=titles[view]||'Farm overview';window.scrollTo({top:0,behavior:'smooth'});if(view==='farms')loadFarms();if(view==='weather')loadWeather();if(view==='market')loadMarket();if(view==='planner')loadActivity()}
$$('[data-view]').forEach(b=>b.addEventListener('click',()=>go(b.dataset.view)));
$$('[data-go]').forEach(b=>b.addEventListener('click',()=>go(b.dataset.go)));
$('#today').textContent=new Intl.DateTimeFormat('en-IN',{weekday:'short',day:'numeric',month:'short',year:'numeric'}).format(new Date());
function formObject(form){return Object.fromEntries(new FormData(form).entries())}
function farmLocation(f){return [f.village, f.district, f.state].filter(Boolean).join(', ') || f.location || 'Location not entered'}
function loadFarms(){farms=read('agri-farms',seed);$('#farm-count').textContent=farms.length;$('#farms-list').innerHTML=farms.map(f=>`<div class="farm-card"><div class="farm-card-icon">♧</div><div class="farm-card-main"><b>${esc(f.name)}</b><small>⌖ ${esc(farmLocation(f))}</small><div class="farm-meta"><span>${esc(f.crop)}</span><span>${esc(f.area_acres)} acres</span><span>pH ${esc(f.soil_ph ?? 'not entered')}</span></div><button class="text-btn farm-open-plan" type="button" data-farm-plan-id="${esc(f.id)}">View personalized plan →</button></div><span class="moisture ${f.moisture==='high'?'wet':f.moisture==='low'?'dry':''}">${f.moisture==='high'?'Wet':f.moisture==='low'?'Dry':'Normal'}</span></div>`).join('')||'<div class="empty-state">No farms added yet.</div>';const selector=$('#farm-plan-select');if(selector){const old=selector.value;selector.innerHTML=farms.map(f=>`<option value="${esc(f.id)}">${esc(f.name)} — ${esc(farmLocation(f))}</option>`).join('');if(farms.some(f=>String(f.id)===old))selector.value=old;}renderFarmPersonalPlan();renderDashboardTasks()}
$('#farm-form').addEventListener('submit',e=>{e.preventDefault();const d=formObject(e.currentTarget);d.location=[d.village,d.district,d.state].filter(Boolean).join(', ');const farm={...d,id:Date.now(),area_acres:Number(d.area_acres||1),soil_ph:d.soil_ph===''?null:Number(d.soil_ph)};farms.push(farm);save();backendPost('/api/farms',farm);e.currentTarget.reset();$('#farm-message').textContent='Farm saved on this device'+(location.protocol==='http:'?' and synced to the local backend when available':'. Run with npm start to enable backend sync.');toast('Farm saved and plan updated');loadFarms();$('#farm-plan-select').value=String(farm.id);renderFarmPersonalPlan()});
const cropInfo=[
{crop:'Wheat',season:['Rabi'],soil:['Loamy','Clay loam'],water:'medium',min:6,max:7.5,temp:[10,25],duration:'medium',cost:[12000,26000],waterLabel:'Medium',note:'Cool-season cereal; avoid waterlogging and check sowing window.',nutrient:'balanced'},
{crop:'Rice',season:['Kharif'],soil:['Clay','Clay loam'],water:'high',min:5.5,max:7,temp:[20,35],duration:'long',cost:[18000,40000],waterLabel:'High',note:'Needs reliable water and suitable drainage/field levelling; not ideal with limited water.',nutrient:'high'},
{crop:'Mustard',season:['Rabi'],soil:['Sandy loam','Loamy'],water:'low',min:6,max:7.5,temp:[10,25],duration:'medium',cost:[8000,18000],waterLabel:'Low',note:'Often a lower-water option; avoid excessive irrigation during flowering.',nutrient:'low'},
{crop:'Maize',season:['Kharif','Spring','Summer'],soil:['Loamy','Sandy loam'],water:'medium',min:5.5,max:7.5,temp:[18,32],duration:'medium',cost:[10000,24000],waterLabel:'Medium',note:'Needs moisture around flowering and well-drained soil.',nutrient:'high'},
{crop:'Chickpea',season:['Rabi'],soil:['Loamy','Sandy loam'],water:'low',min:6,max:8,temp:[10,30],duration:'medium',cost:[7000,16000],waterLabel:'Low',note:'Prefers well-drained soil; waterlogging can harm roots.',nutrient:'low'},
{crop:'Cotton',season:['Kharif'],soil:['Black soil','Loamy'],water:'medium',min:5.8,max:8,temp:[21,35],duration:'long',cost:[18000,42000],waterLabel:'Medium',note:'Long-duration crop; needs regular pest scouting and a suitable local variety.',nutrient:'high'},
{crop:'Tomato',season:['Rabi','Kharif','Spring','Summer'],soil:['Loamy','Sandy loam'],water:'medium',min:5.5,max:7,temp:[18,30],duration:'medium',cost:[25000,70000],waterLabel:'Medium',note:'Higher management and market-price risk; use staking/irrigation suited to local practice.',nutrient:'high'},
{crop:'Potato',season:['Rabi'],soil:['Sandy loam','Loamy'],water:'medium',min:5, max:6.5,temp:[12,25],duration:'short',cost:[25000,60000],waterLabel:'Medium',note:'Needs suitable cool conditions, quality seed tubers and careful disease management.',nutrient:'high'},
{crop:'Sugarcane',season:['Kharif','Spring','Summer'],soil:['Loamy','Clay loam'],water:'high',min:6,max:8,temp:[20,35],duration:'long',cost:[35000,80000],waterLabel:'High',note:'Long-duration, water-demanding crop; confirm local mill/buyer access first.',nutrient:'high'}
];
const cropCostFmt=n=>'₹'+Number(n).toLocaleString('en-IN');
$('#recommend-form').addEventListener('submit',e=>{
  e.preventDefault();
  const d=formObject(e.currentTarget),ph=Number(d.soil_ph),temp=Number(d.temperature),area=Number(d.area),budget=Number(d.budget);
  if(!e.currentTarget.reportValidity())return;
  if(!Number.isFinite(ph)||ph<0||ph>14||!Number.isFinite(temp)||temp< -10||temp>60||area<=0||budget<0){toast('Please check the entered values');return}
  const season=d.season, soil=d.soil_type, water=d.water;
  const scored=cropInfo.map(c=>{
    let score=50, reasons=[], cautions=[];
    if(c.season.includes(season)||season==='Year-round / unsure'){score+=12;reasons.push('season is broadly compatible')}else{score-=14;cautions.push('season timing may not fit')}
    if(ph>=c.min&&ph<=c.max){score+=12;reasons.push('pH is within the crop’s broad range')}else{score-=Math.min(14,Math.abs(ph<(c.min)?c.min-ph:ph-c.max)*5);cautions.push('pH may need local soil-test review')}
    if(c.soil.includes(soil)||(soil==='Sandy'&&c.soil.includes('Sandy loam'))){score+=9;reasons.push('soil type is a broad match')}else if(soil==='Clay'&&c.soil.includes('Clay loam')){score+=3;cautions.push('drainage needs checking')}else{score-=4;cautions.push('soil texture is not the strongest match')}
    if(water===c.water){score+=9;reasons.push('water demand aligns with availability')}else if(water==='low'&&c.water==='high'){score-=20;cautions.push('water demand may exceed supply')}else if(water==='medium'&&c.water==='high'){score-=8;cautions.push('reliable irrigation is important')}else if(water==='high'&&c.water==='low'){score+=1}
    if(temp>=c.temp[0]&&temp<=c.temp[1]){score+=7;reasons.push('entered temperature is broadly suitable')}else{score-=6;cautions.push('temperature may be outside the broad preferred range')}
    if(d.duration==='any'||d.duration===c.duration){score+=5;reasons.push('duration matches your preference')}else{score-=4;cautions.push('crop duration differs from preference')}
    if(d.goal==='low-cost'){if(c.cost[1]<=20000){score+=7;reasons.push('estimated input cost is relatively lower')}else{score-=7;cautions.push('estimated input cost may exceed a low-cost goal')}}
    if(d.goal==='water-saving'){if(c.water==='low'){score+=10;reasons.push('relatively lower water demand')}else if(c.water==='high'){score-=12;cautions.push('not a water-saving option')}}
    if(d.goal==='quick'){if(c.duration==='short'){score+=10;reasons.push('shorter crop duration')}else if(c.duration==='long'){score-=9;cautions.push('long growing period')}}
    if(d.goal==='market'){if(d.market_access==='limited'&&['Tomato','Potato','Cotton','Sugarcane'].includes(c.crop)){score-=6;cautions.push('check buyer/storage/transport before choosing')}else{score+=3;reasons.push('market planning should be checked locally')}}
    if(d.rainfall==='high'&&c.water==='high'){score+=2}else if(d.rainfall==='low'&&c.water==='high'){score-=7;cautions.push('dry outlook may increase irrigation needs')}
    if(d.moisture==='high'&&['Rice','Sugarcane'].includes(c.crop)){score+=2}else if(d.moisture==='high'){score-=5;cautions.push('check drainage before sowing')}
    if(d.moisture==='low'&&c.water==='low'){score+=3;reasons.push('lower water demand may suit dry conditions')}
    if(d.nitrogen==='low'&&c.nutrient==='high'){score-=3;cautions.push('nutrient planning is important; confirm with soil test')}
    if(d.concern==='waterlogging'&&['Chickpea','Mustard','Maize'].includes(c.crop)){score-=5;cautions.push('improve drainage / inspect field first')}
    if(d.concern==='drought'&&c.water==='high'){score-=12;cautions.push('high water demand during drought risk')}
    if(d.concern==='salinity'){score-=3;cautions.push('test soil salinity/EC before crop selection')}
    if(d.concern==='pests'&&['Cotton','Tomato','Potato'].includes(c.crop)){score-=3;cautions.push('plan frequent pest scouting')}
    if(d.previous_crop===c.crop){score-=4;cautions.push('avoid repeating the same crop without rotation advice')}
    const lowTotal=c.cost[0]*area,highTotal=c.cost[1]*area;
    if(budget<lowTotal){score-=12;cautions.push(`estimated input budget starts near ${cropCostFmt(lowTotal)} for this area`)}else if(budget>=highTotal){score+=3;reasons.push('budget covers the broad estimated input range')}
    return {...c,score:Math.max(20,Math.min(95,Math.round(score))),reasons,cautions,lowTotal,highTotal};
  }).sort((a,b)=>b.score-a.score).slice(0,5);
  const loc=[d.village,d.district,d.state].join(', ');
  const cards=scored.map((r,i)=>`<article class="recommend-card shortlist-card"><div class="rank">${String(i+1).padStart(2,'0')}</div><div class="recommend-main"><div class="recommend-title"><b>${esc(r.crop)}</b><span class="score">Fit score ${r.score}/100</span></div><div class="chip-row"><span>${esc(r.season.join(' / '))}</span><span>${esc(r.waterLabel)} water</span><span>${esc(r.duration)} duration</span><span>pH ${r.min}–${r.max}</span></div><p>${esc(r.note)}</p><div class="shortlist-facts"><div><small>Estimated input cost for ${area} acre(s)</small><b>${cropCostFmt(r.lowTotal)}–${cropCostFmt(r.highTotal)}</b></div><div><small>Broad temperature range</small><b>${r.temp[0]}–${r.temp[1]}°C</b></div></div><details><summary>Why this crop ranked here</summary><ul>${r.reasons.slice(0,5).map(x=>`<li>${esc(x)}</li>`).join('')||'<li>Limited matching factors found.</li>'}</ul>${r.cautions.length?`<b>Check before choosing</b><ul>${r.cautions.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:''}</details><a class="outline-btn shortlist-map-link" target="_blank" rel="noopener noreferrer" href="https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(r.crop+' seeds agricultural market '+loc)}">Explore local ${esc(r.crop)} seed/market results ↗</a></div></article>`).join('');
  const html=`<div class="shortlist-summary"><span class="welcome-kicker">YOUR FARM PROFILE</span><h4>${esc(loc)}</h4><div class="farm-meta"><span>${area} acres</span><span>${esc(soil)} soil</span><span>${esc(season)}</span><span>Budget ${cropCostFmt(budget)}</span></div><p>Top ${scored.length} options ranked from the details you entered. Fit scores are heuristic rankings, not probabilities of success.</p></div><div class="result-stack">${cards}</div><div class="shortlist-actions"><button class="outline-btn" id="save-recommendation" type="button">Save shortlist on this device</button><button class="outline-btn" id="print-recommendation" type="button">Print / Save as PDF</button></div><p class="result-disclaimer">Cost ranges are illustrative starter estimates, not current local quotes or profit guarantees. Market prices, yield, seed availability and crop suitability vary by district, variety and season. Confirm with current local agriculture advice and a soil test.</p>`;
  $('#recommend-results').innerHTML=html;
  $('#save-recommendation')?.addEventListener('click',async()=>{const record={date:new Date().toISOString(),location:loc,inputs:d,shortlist:scored.map(c=>({crop:c.crop,score:c.score,cost:[c.lowTotal,c.highTotal]}))};const key='agropilot-crop-shortlists-v1';let old=[];try{old=JSON.parse(localStorage.getItem(key)||'[]')}catch{};localStorage.setItem(key,JSON.stringify([record,...old].slice(0,10)));const synced=await backendPost('/api/shortlists',record);toast(synced?'Shortlist saved locally and to backend':'Shortlist saved on this device')});
  $('#print-recommendation')?.addEventListener('click',()=>window.print());
  $('#recommend-results').scrollIntoView({behavior:'smooth',block:'start'});
});
$('#diagnose-form').addEventListener('submit',e=>{
  e.preventDefault();
  const d=formObject(e.currentTarget),sym=$$('input[name="symptoms"]:checked').map(x=>x.value);
  const has=(x)=>sym.includes(x), causes=[];
  const add=(key,title,why,evidence,checks,urgency='Monitor')=>causes.push({key,title,why,evidence,checks,urgency,score:0});
  if(d.moisture==='low'||d.irrigation==='long_ago'||(d.leaf_color==='wilting'&&d.moisture!=='high')) add('dry','Water stress (too little available water)','Dry soil, recent lack of irrigation or wilting can fit water stress, but wilting alone is not proof.',['Soil moisture: '+d.moisture,'Recent irrigation: '+d.irrigation,'Leaf condition: '+d.leaf_color],['Check moisture in the active root zone at several points','Compare affected plants with healthy plants','Check irrigation coverage and crop growth stage'],'High');
  if(d.moisture==='high'||d.recent_rain==='yes'||d.irrigation==='recent'||d.root_condition==='dark_soft') add('wet','Excess water / drainage or root-zone stress','Wet soil, recent rain or dark/soft roots can be consistent with waterlogging or root problems; inspect before watering again.',['Soil moisture: '+d.moisture,'Recent rain: '+d.recent_rain,'Root condition: '+d.root_condition],['Look for standing water and blocked drainage','Inspect roots on a small number of affected plants','Do not add water until root-zone moisture is checked'],'High');
  if(d.leaf_color==='yellow'||has('yellow leaves')||d.leaf_color==='brown'||has('stunted growth')) add('nutrient','Nutrient imbalance or uptake problem','Yellowing, browning or slow growth can be related to nutrients, pH, root stress, salinity or disease; appearance alone cannot identify a specific deficiency.',['Leaf colour: '+d.leaf_color,'Fertilizer history: '+d.fertilizer,'Crop stage: '+d.growth_stage],['Check whether symptoms appear on older or newer leaves','Review fertilizer history and irrigation quality','Use a soil test before applying a nutrient or changing pH'],'Monitor');
  if(d.leaf_color==='brown'||has('brown spots')) add('disease','Possible leaf disease or environmental injury','Spots and dry edges have several possible causes, including disease, heat, spray injury and nutrient or water stress.',['Brown/black spots selected: '+has('brown spots'),'Affected spread: '+d.spread],['Photograph both sides of several leaves in natural light','Check whether spots are spreading and whether stems are affected','Ask a local agriculture officer or plant clinic to confirm before treatment'],'High');
  if(has('holes in leaves')||d.pest_signs==='yes') add('pest','Possible insect or other pest damage','Leaf holes plus visible insects, larvae, webbing or droppings increase suspicion of pest damage, but the pest still needs identification.',['Pest signs: '+d.pest_signs,'Holes in leaves selected: '+has('holes in leaves')],['Inspect leaf undersides and new growth early in the day','Look for larvae, eggs, webbing and fresh droppings','Use local integrated-pest-management guidance after identifying the pest'],'High');
  if(d.root_condition==='dark_soft'||d.root_condition==='dry_damaged'||has('wilting')||d.leaf_color==='wilting') add('root','Root or stem stress needs inspection','Wilting with root/stem changes can indicate root damage, rot or water stress. These causes cannot be distinguished from this form alone.',['Root condition: '+d.root_condition,'Leaf condition: '+d.leaf_color],['Inspect roots and stem base on a few affected plants','Compare with a healthy plant from the same field','Seek expert review if damage is spreading or plants collapse'],'High');
  if(!causes.length) add('unknown','Not enough evidence yet','The current observations do not point strongly to one cause. Avoid guessing or applying a treatment.',['No strong symptom pattern selected'],['Select all visible symptoms','Record when the issue started and whether it is spreading','Check moisture, roots, pests and recent weather']);
  // Transparent heuristic ranking, not a trained model or calibrated probability.
  causes.forEach(c=>{
    if(c.key==='dry'){if(d.moisture==='low')c.score+=3;if(d.irrigation==='long_ago')c.score+=2;if(d.leaf_color==='wilting'||has('wilting'))c.score+=2;if(d.recent_rain==='yes')c.score-=1}
    if(c.key==='wet'){if(d.moisture==='high')c.score+=3;if(d.recent_rain==='yes')c.score+=1;if(d.irrigation==='recent')c.score+=1;if(d.root_condition==='dark_soft')c.score+=2}
    if(c.key==='nutrient'){if(d.leaf_color==='yellow'||has('yellow leaves'))c.score+=2;if(has('stunted growth'))c.score+=1;if(d.fertilizer==='no')c.score+=1}
    if(c.key==='disease'){if(has('brown spots'))c.score+=2;if(d.spread==='many')c.score+=1}
    if(c.key==='pest'){if(has('holes in leaves'))c.score+=2;if(d.pest_signs==='yes')c.score+=3}
    if(c.key==='root'){if(d.root_condition==='dark_soft'||d.root_condition==='dry_damaged')c.score+=3;if(has('wilting'))c.score+=1}
    if(d.spread==='many'&&['disease','wet','root'].includes(c.key))c.score+=1;
  });
  causes.sort((a,b)=>b.score-a.score);
  const ranked=causes.map((c,i)=>`<div class="finding-card"><div class="finding-top"><span class="finding-number">0${i+1}</span><span class="confidence">${i===0&&c.score>=4?'Higher clue match':'Possible cause'}</span></div><h4>${esc(c.title)}</h4><p>${esc(c.why)}</p><b class="next-label">Why this is being considered</b><ul>${c.evidence.map(a=>`<li>${esc(a)}</li>`).join('')}</ul><b class="next-label">Recommended next checks</b><ul>${c.checks.map(a=>`<li>${esc(a)}</li>`).join('')}</ul>${c.urgency==='High'?'<p class="result-disclaimer">Priority: inspect soon, especially if damage is spreading.</p>':''}</div>`).join('');
  const spreadNote=d.spread==='many'?'Many plants are affected: compare multiple areas and contact a local agricultural expert promptly if the problem is spreading.':d.spread==='edge'?'Damage near field edges can be related to field-edge pests, spray drift or local conditions; compare with the field centre.':'Only a few plants are affected: mark them and inspect nearby plants for changes.';
  const farmLocation=[d.village,d.district,d.state].filter(Boolean).join(', ');
  const farmerSummary=(d.farmer_name||farmLocation||d.crop_variety||d.affected_area)?`<div class="farm-detail-summary"><b>Submitted farm details</b><p>${d.farmer_name?`Farmer: ${esc(d.farmer_name)} · `:''}Crop: ${esc(d.crop)}${d.crop_variety?` (${esc(d.crop_variety)})`:''}${farmLocation?` · Location: ${esc(farmLocation)}`:''}${d.affected_area?` · Affected area: ${esc(d.affected_area)} acres`:''}${d.planting_date?` · Planting date: ${esc(d.planting_date)}`:''}</p><small>Details are saved in this browser on this device.</small></div>`:'';
  $('#diagnose-results').innerHTML=`<div class="result-stack">${farmerSummary}<div class="notice"><span>ⓘ</span><p><b>Preliminary triage for ${esc(d.crop)}</b><br>${esc(spreadNote)} These are ranked clues from your answers, not calibrated confidence scores or a confirmed diagnosis.</p></div>${ranked}<p class="result-disclaimer">Image AI runs separately when a trained TensorFlow.js model is installed in models/crop-doctor/. If the model is not installed, this screen provides symptom-based triage only. Do not apply pesticides or fertilizers based only on this result; confirm disease or nutrient issues with a local agriculture officer, KVK or soil test.</p></div>`;
  const triageRecord={crop:d.crop,location:farmLocation,observations:d,symptoms:sym,leadingClue:causes[0]?.title||'More observations needed',createdAt:new Date().toISOString()};backendPost('/api/data/cropScans',triageRecord);activities=[{task:`Crop health triage: ${d.crop}`,farm:'User-submitted observations',priority:causes[0]?.urgency||'Medium',reason:`Leading clue: ${causes[0]?.title||'More observations needed'}. Follow-up: ${spreadNote}`,created_at:new Date().toLocaleString()},...activities].slice(0,20);save();loadActivity();toast('Crop triage complete');
});

// Advanced crop-health toolkit: transparent rules, photo comparison, reports and history.
const healthReportKey='agropilot-health-reports-v1';
let healthReports=read(healthReportKey,[]);
function healthPhotoData(file){return new Promise((resolve,reject)=>{if(!file)return resolve(null);if(!['image/jpeg','image/png','image/webp'].includes(file.type))return reject(new Error('Choose a JPEG, PNG, or WebP photo.'));if(file.size>4*1024*1024)return reject(new Error('Each photo must be 4 MB or smaller.'));const reader=new FileReader();reader.onload=()=>resolve({dataUrl:reader.result,name:file.name,type:file.type,size:file.size});reader.onerror=()=>reject(new Error('Could not read selected photo.'));reader.readAsDataURL(file)})}
function showHealthPhotoCompare(){const before=$('#health-before-photo')?.files?.[0],after=$('#health-after-photo')?.files?.[0],host=$('#health-photo-compare');if(!host)return;const parts=[];if(before)parts.push(`<div><b>Before</b><img alt="Before crop condition" src="${URL.createObjectURL(before)}"></div>`);if(after)parts.push(`<div><b>Current</b><img alt="Current crop condition" src="${URL.createObjectURL(after)}"></div>`);host.innerHTML=parts.length?parts.join('')+'<small>Visual comparison only; lighting and angle can affect appearance.</small>':'<p class="field-help">No comparison photos selected.</p>'}
$('#health-before-photo')?.addEventListener('change',showHealthPhotoCompare);$('#health-after-photo')?.addEventListener('change',showHealthPhotoCompare);
function makeHealthAssessment(d){let score=100,findings=[],actions=[];const affected=Number(d.affectedPercent||0),ph=d.ph===''?null:Number(d.ph),humidity=d.humidity===''?null:Number(d.humidity),temp=d.temperature===''?null:Number(d.temperature);
 if(d.severity==='mild'){score-=8;findings.push('Mild symptom severity selected.')}else if(d.severity==='moderate'){score-=20;findings.push('Moderate symptoms selected; monitor affected plants closely.')}else{score-=35;findings.push('Severe symptoms selected; arrange prompt local expert inspection.');actions.push('Contact a local agriculture officer/KVK or plant clinic promptly, especially if the damage is spreading.');}
 if(affected>=50){score-=25;findings.push(`${affected}% of plants reported affected: widespread field scouting is important.`);actions.push('Inspect multiple zones and compare affected plants with a healthy patch.')}else if(affected>=20){score-=12;findings.push(`${affected}% affected: check whether symptoms are spreading.`)}
 if(d.waterStress==='dry'){score-=15;findings.push('Dry soil/wilting may fit water stress; check moisture at root depth.');actions.push('Check root-zone moisture, irrigation coverage and crop stage before watering.')}if(d.waterStress==='wet'){score-=15;findings.push('Wet soil/standing water may indicate drainage or root-zone stress.');actions.push('Inspect drainage and roots; do not add water until field conditions are checked.');}
 if(d.nitrogen==='low'||d.phosphorus==='low'||d.potassium==='low'){score-=8;findings.push('A low nutrient status was entered from a soil report; interpret it against crop and growth stage.');actions.push('Use the actual lab report and crop-specific local recommendations before applying fertilizer.');}
 if(d.nitrogen==='unknown'||d.phosphorus==='unknown'||d.potassium==='unknown'){findings.push('One or more NPK values are unknown; no nutrient deficiency can be confirmed from this form.');actions.push('Consider a recognised soil test before changing fertilizer or soil amendments.');}
 if(ph!==null&&(ph<5.5||ph>8)){score-=8;findings.push(`Entered pH ${ph} may need crop-specific interpretation and lab confirmation.`);actions.push('Confirm pH and salinity/EC with a soil-testing lab before applying amendments.');}
 if(d.pest==='yes'){score-=10;findings.push('Visible pest evidence reported; inspect both sides of leaves and stems.');actions.push('Photograph the pest and damage; confirm identification before using crop-protection products.');}
 if(humidity!==null&&humidity>=80&&d.rain==='heavy'){score-=8;findings.push('High humidity plus heavy recent rain can favour some crop diseases, depending on crop and pathogen; this is a weather-linked risk clue, not a forecast or diagnosis.');actions.push('Scout leaves and stems after rain and follow local crop-specific disease advisories.');}
 if(temp!==null&&(temp<5||temp>38)){findings.push(`Entered temperature ${temp}°C may stress some crops; crop and growth stage determine actual risk.`);actions.push('Check crop-specific temperature guidance and local forecast before field operations.');}
 if(d.rain==='heavy'){findings.push('Heavy recent rain reported: inspect drainage and field access.');actions.push('Check standing water and avoid field operations when conditions are unsafe.');}
 if(d.severity!=='severe'&&affected<20)actions.push('Mark a few affected plants and re-check them in 2–3 days under similar lighting.');actions.push('Take clear photos of both sides of leaves and record when symptoms started.');if(!actions.some(a=>a.toLowerCase().includes('expert'))&&affected>=20)actions.push('If symptoms continue to spread, seek a local agriculture expert’s assessment.');
 if(!findings.length)findings.push('No strong risk clues were entered. Continue regular scouting; this does not prove the crop is disease-free.');return {score:Math.max(0,Math.min(100,score)),findings,actions,inputs:d,createdAt:new Date().toISOString(),id:Date.now()}}
function renderHealthReportHistory(){const host=$('#health-report-history');if(!host)return;if(!healthReports.length){host.innerHTML='<div class="empty-state"><b>No health reports saved yet</b><p>Generate a report to build your crop health history.</p></div>';return}host.innerHTML=healthReports.slice(0,20).map((r,i)=>`<article class="decision-card"><div class="decision-card-top"><span class="status-tag">${esc(r.crop||'Crop')}</span><span class="priority ${r.assessment?.score<60?'high':r.assessment?.score<80?'medium':'low'}">Indicator ${Number(r.assessment?.score??0)}/100</span></div><h4>${esc(r.createdAt?new Date(r.createdAt).toLocaleString('en-IN'):'Saved report')}</h4><p>${esc((r.assessment?.findings||[]).slice(0,2).join(' '))}</p><button type="button" class="outline-btn" data-health-report="${i}">View report</button></article>`).join('')}
$('#advanced-health-form')?.addEventListener('submit',async e=>{e.preventDefault();const d=formObject(e.currentTarget);if(!e.currentTarget.reportValidity())return;let before=null,after=null;try{before=await healthPhotoData($('#health-before-photo')?.files?.[0]);after=await healthPhotoData($('#health-after-photo')?.files?.[0])}catch(err){toast(err.message);return}const assessment=makeHealthAssessment(d),diagnoseCrop=$('#diagnose-form')?.elements?.crop?.value||'Not specified',record={crop:diagnoseCrop,location:[$('#diagnose-form')?.elements?.village?.value,$('#diagnose-form')?.elements?.district?.value,$('#diagnose-form')?.elements?.state?.value].filter(Boolean).join(', '),assessment,notes:d.notes||'',photos:{beforeName:before?.name||'',afterName:after?.name||''},createdAt:assessment.createdAt};
 for(const [key,photo] of [['before',before],['after',after]]){if(!photo)continue;const uploaded=await backendPost('/api/uploads',{dataUrl:photo.dataUrl,originalName:photo.name,crop:record.crop,location:record.location,photoRole:`health-${key}`});if(uploaded?.item)record.photos[`${key}Url`]=uploaded.item.url;}
 healthReports=[record,...healthReports].slice(0,50);localStorage.setItem(healthReportKey,JSON.stringify(healthReports));const synced=await backendPost('/api/data/healthReports',record);const risk=assessment.score<60?'Needs prompt review':assessment.score<80?'Monitor closely':'No major rule-based flags entered';
 $('#advanced-health-results').innerHTML=`<div class="health-report-print"><div class="health-score-card"><div><span class="welcome-kicker">RULE-BASED PLANT HEALTH INDICATOR</span><div class="health-score-number">${assessment.score}<small>/100</small></div><b>${esc(risk)}</b></div><p>Indicator only—not a disease probability or proof of healthy crop. Generated ${esc(new Date(record.createdAt).toLocaleString('en-IN'))}.</p></div><div class="health-report-grid"><section><h4>Assessment findings</h4><ul>${assessment.findings.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></section><section><h4>Personalized action plan</h4><ol>${assessment.actions.map(x=>`<li>${esc(x)}</li>`).join('')}</ol></section></div><section class="health-report-notes"><h4>Notes & observations</h4><p>${esc(d.notes||'No extra notes entered.')}</p><p><b>Crop stage:</b> ${esc(d.stage)} · <b>Severity:</b> ${esc(d.severity)} · <b>Reported affected:</b> ${esc(d.affectedPercent)}%</p>${record.photos.beforeUrl||record.photos.afterUrl?`<p>Saved photos: ${record.photos.beforeUrl?`<a href="${esc(record.photos.beforeUrl)}" target="_blank" rel="noopener noreferrer">Before photo</a>`:''} ${record.photos.afterUrl?`<a href="${esc(record.photos.afterUrl)}" target="_blank" rel="noopener noreferrer">Current photo</a>`:''}</p>`:''}</section><div class="shortlist-actions"><button class="outline-btn" type="button" id="print-health-report">Print / Save as PDF</button><button class="outline-btn" type="button" id="save-health-recovery">Add follow-up reminder</button></div><p class="result-disclaimer">This report uses entered observations and simple rules only. It does not diagnose disease, validate nutrient deficiency, or provide pesticide dosage. Consult a qualified local expert for severe or spreading symptoms.</p></div>`;
 $('#print-health-report')?.addEventListener('click',()=>window.print());$('#save-health-recovery')?.addEventListener('click',()=>{const log={crop:record.crop,condition:'uncertain',action:'Follow up on Crop Health report',notes:`Re-check in 2–3 days. ${assessment.findings[0]||''}`,date:new Date(Date.now()+2*86400000).toLocaleDateString('en-IN')};recoveryLogs=[log,...recoveryLogs].slice(0,100);persistList(recoveryKey,recoveryLogs);renderRecovery();toast('Follow-up added to recovery tracker')});renderHealthReportHistory();toast(synced?'Health report saved and synced to backend':'Health report saved on this device');});
$('#refresh-health-reports')?.addEventListener('click',async()=>{const result=await fetch('/api/data/healthReports').then(r=>r.ok?r.json():null).catch(()=>null);if(result?.items){const seen=new Set(healthReports.map(r=>r.createdAt));healthReports=[...healthReports,...result.items.filter(r=>!seen.has(r.createdAt))].slice(0,50);localStorage.setItem(healthReportKey,JSON.stringify(healthReports));renderHealthReportHistory();toast('Health report history refreshed')}else{renderHealthReportHistory();toast('Showing this device history; start npm start for backend sync')}});
$('#health-report-history')?.addEventListener('click',e=>{const b=e.target.closest('[data-health-report]');if(!b)return;const r=healthReports[Number(b.dataset.healthReport)];if(!r)return;$('#advanced-health-results').innerHTML=`<div class="health-report-print"><div class="health-score-card"><div><span class="welcome-kicker">SAVED REPORT</span><div class="health-score-number">${Number(r.assessment?.score??0)}<small>/100</small></div></div><p>${esc(r.createdAt?new Date(r.createdAt).toLocaleString('en-IN'):'')}</p></div><h4>Findings</h4><ul>${(r.assessment?.findings||[]).map(x=>`<li>${esc(x)}</li>`).join('')}</ul><h4>Action plan</h4><ol>${(r.assessment?.actions||[]).map(x=>`<li>${esc(x)}</li>`).join('')}</ol><p>${esc(r.notes||'No notes')}</p><button class="outline-btn" type="button" id="print-health-report">Print / Save as PDF</button><p class="result-disclaimer">Rule-based tracking only; not a confirmed diagnosis.</p></div>`;$('#print-health-report')?.addEventListener('click',()=>window.print());$('#advanced-health-results').scrollIntoView({behavior:'smooth',block:'start'})});
renderHealthReportHistory();
async function loadWeather(){const lat=$('#lat').value||'28.9931',lon=$('#lon').value||'77.0151';$('#weather-results').innerHTML='<div class="loading">Getting forecast…</div>';try{const r=await fetch(`https://api.open-meteo.com/v1/forecast?latitude=${encodeURIComponent(lat)}&longitude=${encodeURIComponent(lon)}&current=temperature_2m,relative_humidity_2m,precipitation&daily=temperature_2m_max,temperature_2m_min,precipitation_probability_max&timezone=auto&forecast_days=4`);if(!r.ok)throw Error('weather unavailable');const w=await r.json();currentWeather={live:true,rain_probability:w.daily.precipitation_probability_max?.[0]||0};$('#weather-status').textContent='Live data';const c=w.current,days=w.daily.time.map((date,i)=>({date,max_temp:w.daily.temperature_2m_max[i],min_temp:w.daily.temperature_2m_min[i],rain_probability:w.daily.precipitation_probability_max[i]}));$('#weather-results').innerHTML=`<div class="weather-hero"><div class="weather-current"><div><span class="weather-eyebrow">LIVE FORECAST · OPEN-METEO</span><div class="temperature">${Math.round(c.temperature_2m)}<sup>°C</sup></div><p>Current temperature</p><div class="weather-mini">Humidity <b>${c.relative_humidity_2m}%</b> &nbsp; Rain <b>${c.precipitation} mm</b></div></div><div class="weather-sun">☀</div></div><div class="weather-advice"><span>✦ FIELD NOTE</span><p>${currentWeather.rain_probability>50?'Rain chance is high. Check soil moisture before irrigation and plan field work carefully.':'Check actual soil moisture before irrigating; forecasts are only one part of the decision.'}</p></div></div><div class="forecast-grid">${days.map(d=>`<div class="forecast-card"><small>${d.date}</small><span class="forecast-icon">${d.rain_probability>40?'🌧':'⛅'}</span><b>${Math.round(d.max_temp)}° / ${Math.round(d.min_temp)}°C</b><span class="rain-label">☂ ${d.rain_probability??'—'}% rain chance</span></div>`).join('')}</div><p class="result-disclaimer">Forecast by Open-Meteo. Confirm conditions at the field.</p>`}catch(e){currentWeather={live:false,rain_probability:20};$('#weather-status').textContent='Demo fallback';$('#weather-results').innerHTML=`<div class="weather-hero"><div class="weather-current"><div><span class="weather-eyebrow">DEMO WEATHER · OFFLINE FALLBACK</span><div class="temperature">27<sup>°C</sup></div><p>Partly cloudy · sample values</p><div class="weather-mini">Humidity <b>58%</b> &nbsp; Rain <b>0 mm</b></div></div><div class="weather-sun">⛅</div></div><div class="weather-advice"><span>✦ FIELD NOTE</span><p>Live forecast unavailable. Check a trusted local forecast and actual soil moisture before irrigation.</p></div></div><div class="forecast-grid">${[0,1,2,3].map((x)=>`<div class="forecast-card"><small>${new Date(Date.now()+x*86400000).toLocaleDateString('en-IN',{weekday:'short',day:'numeric',month:'short'})}</small><span class="forecast-icon">⛅</span><b>30° / 20°C</b><span class="rain-label">☂ 20% rain chance</span></div>`).join('')}</div><p class="result-disclaimer">Sample values only; not live weather data.</p>`}}
$('#refresh-weather').addEventListener('click',loadWeather);
function loadMarket(){$('#market-body').innerHTML=prices.map(p=>`<tr><td><b>${p[0]}</b></td><td>Sonipat (sample)</td><td class="price-cell">₹${p[1].toLocaleString('en-IN')}</td><td><span class="trend ${p[2].toLowerCase()}">${p[2]}</span></td></tr>`).join('');$('#market-source').textContent='Illustrative sample values only, not live mandi rates. Verify with official mandi sources.'}
function buildTasks(rain){let tasks=[];farms.forEach(f=>{if(f.moisture==='high')tasks.push({task:'Inspect drainage',farm:f.name,priority:'High',reason:'Soil moisture is marked wet; check standing water and root-zone drainage.'});else if(f.moisture==='low'&&rain<50)tasks.push({task:'Check irrigation need',farm:f.name,priority:'High',reason:'Soil is marked dry and forecast rain probability is below 50%.'});else if(rain>=50)tasks.push({task:'Recheck irrigation after forecast',farm:f.name,priority:'Medium',reason:'Rain is possible; verify soil moisture before watering.'});else tasks.push({task:'Scout crop health',farm:f.name,priority:'Medium',reason:`Inspect ${f.crop} for pests, disease and nutrient symptoms.`});tasks.push({task:'Review crop observations',farm:f.name,priority:'Low',reason:'Record crop stage and recent field changes.'})});return tasks}
function taskMarkup(t){return `<div class="task-row"><span class="task-check">✓</span><div class="task-copy"><b>${esc(t.task)}</b><small>${esc(t.farm)} · Today</small><p>${esc(t.reason)}</p></div><span class="priority ${t.priority.toLowerCase()}">${t.priority}</span></div>`}
function generatePlan(){const tasks=buildTasks(Number($('#rain-prob').value||0));activities=[...tasks.map(t=>({...t,created_at:new Date().toLocaleString()})),...activities].slice(0,20);save();$('#plan-results').innerHTML=`<div class="plan-summary"><div><span>GENERATED</span><b>${tasks.length} suggested actions</b><small>${new Date().toLocaleString()}</small></div><div class="plan-total-icon">✦</div></div><div class="plan-task-list">${tasks.map(taskMarkup).join('')}</div><p class="result-disclaimer">Suggestions only. Review field conditions before taking action.</p>`;loadActivity();renderDashboardTasks();toast('Farm plan generated')}
$('#generate-plan').addEventListener('click',generatePlan);
function loadActivity(){activities=read('agri-activities',[]);$('#activity-list').innerHTML=activities.length?activities.slice(0,8).map(a=>`<div class="activity-row"><span class="activity-dot"></span><div><b>${esc(a.task)}</b><small>${esc(a.farm)} · ${esc(a.reason)}</small></div><span class="priority ${String(a.priority).toLowerCase()}">${esc(a.priority)}</span></div>`).join(''):'<p class="muted">No activity logged yet. Generate an operations plan first.</p>'}
function renderDashboardTasks(){if(!$('#dashboard-tasks'))return;const tasks=buildTasks(20);$('#dashboard-tasks').innerHTML=tasks.slice(0,3).map(t=>`<div class="mini-task"><span class="mini-task-dot"></span><div><b>${esc(t.task)}</b><small>${esc(t.farm)} · ${esc(t.priority)} priority</small></div></div>`).join('')}
function addMessage(text,who){const div=document.createElement('div');div.className=`chat-bubble ${who}`;div.textContent=text;$('#chat-messages').appendChild(div);$('#chat-messages').scrollTop=$('#chat-messages').scrollHeight;return div}
function assistantReply(m){const s=m.toLowerCase();if(/yellow|nutrient|yellowing/.test(s))return 'Yellow leaves can result from nutrient deficiency, overwatering, poor drainage or disease. Check soil moisture, inspect roots and compare affected plants with healthy ones. A soil test can help confirm nutrient needs.';if(/irrigat|water|rain|over/.test(s))return 'Before irrigation, check soil moisture near the root zone, crop growth stage and recent rainfall. If soil is already wet or rain is likely, delay and reassess. Avoid using a fixed schedule without field checks.';if(/price|sell|market|mandi/.test(s))return 'Check today’s official mandi price for your crop and quality grade. Compare at least two nearby markets and calculate transport, handling and commission costs to estimate net return. Prices shown in this demo are samples.';if(/pest|hole|insect|spot|disease/.test(s))return 'Inspect both sides of leaves and several plants; note whether symptoms are spreading and look for pests. Take clear photos and consult a local agriculture officer before choosing a treatment. Do not spray based only on a guess.';if(/soil|ph|fertiliz|nutrition/.test(s))return 'Use a soil test to guide pH and nutrient decisions. Check the crop, growth stage, past fertilizer applications and soil moisture. Avoid adding fertilizer without knowing the likely deficiency.';if(/crop|recommend|plant/.test(s))return 'Crop choice depends on season, soil type and pH, water availability, local temperature and market access. Open Crop recommendation to compare starter suggestions, then confirm with local agricultural guidance.';return 'Start by observing the crop and recording when the issue began, recent rain/irrigation, soil moisture and visible symptoms. I can help with crop care, soil, irrigation, pests and market planning. This demo assistant provides general guidance, not a confirmed diagnosis.'}
function sendChat(message){if(!message.trim())return;addMessage(message,'user');$('#chat-input').value='';const wait=addMessage(assistantReply(message),'bot');const meta=document.createElement('small');meta.textContent='Agri Assistant · rules-based demo';wait.appendChild(meta)}
$('#chat-form').addEventListener('submit',e=>{e.preventDefault();sendChat($('#chat-input').value)});$$('[data-prompt]').forEach(b=>b.addEventListener('click',()=>sendChat(b.dataset.prompt)));

// Extended hackathon demo: explainable decisions, scenario calculator, field zones and voice input.
Object.assign(titles,{decision:'Autonomous decision engine',impact:'Water & profit simulator',fieldmap:'Field health zones'});
const originalGo=go;
go=function(view){originalGo(view);};

$('#decision-form')?.addEventListener('submit',e=>{
  e.preventDefault();const d=formObject(e.currentTarget),rain=Number(d.rain),items=[];
  if(d.moisture==='high')items.push({p:'High',title:'Inspect drainage first',why:'The field is marked wet. Check for standing water and root-zone drainage before adding more water.'});
  else if(d.moisture==='low'&&rain>=50)items.push({p:'High',title:'Verify soil before irrigation',why:`Soil is marked dry but rain probability is ${rain}%. Check root-zone moisture and forecast timing before watering.`});
  else if(d.moisture==='low')items.push({p:'High',title:'Check irrigation need',why:'Soil is marked dry and rain probability is below 50%. Confirm moisture at the root zone and crop stage before irrigating.'});
  else items.push({p:'Medium',title:'Continue moisture monitoring',why:'Moisture is marked medium. Recheck the root zone and avoid a fixed schedule without field observations.'});
  if(d.condition==='yellow')items.push({p:'High',title:'Investigate yellowing',why:'Possible causes include nutrient issues, waterlogging or disease. Compare affected plants, inspect drainage and use a soil test before applying nutrients.'});
  if(d.condition==='wilting')items.push({p:'High',title:'Inspect wilting plants',why:'Wilting can relate to dry soil, root stress or disease. Check moisture and roots before deciding on irrigation.'});
  if(d.condition==='spots')items.push({p:'Medium',title:'Scout leaf damage',why:'Inspect both leaf sides and several plants for spreading spots or pests. Avoid chemical treatment based on a guess.'});
  if(d.condition==='stunted')items.push({p:'Medium',title:'Compare growth conditions',why:'Compare affected and healthy plants, check moisture and roots, and consider soil testing.'});
  if(rain>=70)items.push({p:'Medium',title:'Prepare for possible rain',why:'Forecast probability is high. Check local forecast, drainage and safe field access; reassess after rainfall.'});
  items.push({p:'Low',title:'Log the next observation',why:`Record ${d.crop}, ${d.stage.toLowerCase()} stage, date and any changes after the chosen action.`});
  $('#decision-results').innerHTML=`<div class="decision-list">${items.map((x,i)=>`<article class="decision-card"><div class="decision-card-top"><span class="rank">${String(i+1).padStart(2,'0')}</span><span class="priority ${x.p.toLowerCase()}">${x.p} priority</span></div><h4>${esc(x.title)}</h4><p>${esc(x.why)}</p><button class="outline-btn log-decision" data-task="${esc(x.title)}" data-reason="${esc(x.why)}">Log for follow-up</button></article>`).join('')}<p class="result-disclaimer">Recommendations are rule-based examples using your inputs; they are not live sensor readings or expert diagnosis.</p></div>`;
});
$('#decision-results')?.addEventListener('click',e=>{const b=e.target.closest('.log-decision');if(!b)return;activities=[{task:b.dataset.task,farm:'Decision Engine',priority:'Medium',reason:b.dataset.reason,created_at:new Date().toLocaleString()},...read('agri-activities',[])].slice(0,20);localStorage.setItem('agri-activities',JSON.stringify(activities));backendPost('/api/activities',activities[0]);toast('Action saved to activity log')});

$('#impact-form')?.addEventListener('submit',e=>{
  e.preventDefault();const d=formObject(e.currentTarget),area=Number(d.area),yieldA=Number(d.yield),price=Number(d.price),cost=Number(d.cost),transport=Number(d.transport),production=area*yieldA,revenue=production*price,total=cost+transport,profit=revenue-total,breakEven=production?total/production:0;
  let waterNote=d.moisture==='high'?'Soil is marked wet: inspect drainage and avoid watering until field moisture is checked.':d.moisture==='low'&&Number(d.rain)>=60?'Soil is marked dry but rain chance is high: verify the root zone and forecast timing before irrigation.':d.moisture==='low'?'Soil is marked dry: inspect root-zone moisture and crop stage to decide whether irrigation is needed.':'Moisture is marked medium: monitor the root zone and use crop-stage guidance.';
  const money=n=>'₹'+Math.round(n).toLocaleString('en-IN');
  $('#impact-results').innerHTML=`<div class="impact-metrics"><div><small>Estimated revenue</small><b>${money(revenue)}</b></div><div><small>Estimated total costs</small><b>${money(total)}</b></div><div class="${profit>=0?'positive':'negative'}"><small>Estimated net return</small><b>${money(profit)}</b></div><div><small>Break-even price</small><b>${money(breakEven)} / quintal</b></div></div><div class="impact-bar"><span>Revenue</span><div><i style="width:${revenue+total?Math.min(100,revenue/(revenue+total)*100):0}%"></i></div><b>${money(revenue)}</b></div><div class="impact-bar"><span>Costs</span><div><i class="cost-fill" style="width:${revenue+total?Math.min(100,total/(revenue+total)*100):0}%"></i></div><b>${money(total)}</b></div><div class="water-advice-card"><b>Water planning note · ${esc(d.crop)}</b><p>${esc(waterNote)}</p><small>Output uses your estimates: ${production.toLocaleString('en-IN')} quintals expected across ${area} acres. It does not predict actual yield.</small></div><p class="result-disclaimer">Illustrative calculation only. Excludes any costs you did not enter, taxes, quality variation and market volatility.</p>`;
});

const fieldInspectionKey='agri-field-inspections-v1';
let fieldInspections=read(fieldInspectionKey,[]);
function fieldPriority(d){let score=0,why=[];if(d.condition==='wilting'){score+=3;why.push('Wilting can indicate water stress, root damage or disease.')}if(d.condition==='spots'||d.condition==='pest'){score+=2;why.push('Leaf damage or pest signs need closer scouting.')}if(d.condition==='yellow'||d.condition==='stunted'){score+=1;why.push('Check nutrient status, moisture, roots and crop stage.')}if(d.moisture==='dry'){score+=2;why.push('Check moisture at root depth and recent rainfall before irrigation.')}if(d.moisture==='wet'||d.waterlogging==='yes'){score+=3;why.push('Inspect drainage and standing water; avoid adding irrigation until checked.')}if(d.spread==='many'){score+=2;why.push('Widespread symptoms should be checked promptly.')}let priority=score>=5?'High':score>=2?'Medium':'Routine';if(!why.length)why.push('No major concern was selected. Continue routine scouting and record changes.');return {score,priority,why}}
function renderFieldInspections(){const host=$('#field-inspection-history');if(!host)return;if(!fieldInspections.length){host.innerHTML='<div class="empty-state"><b>No saved inspections yet</b><p>Record an observation above to build your field history.</p></div>';return}host.innerHTML=fieldInspections.map((r,i)=>`<div class="decision-card"><div class="decision-card-top"><span class="status-tag">${esc(r.field)} · ${esc(r.zone)}</span><span class="priority ${r.priority==='High'?'high':r.priority==='Routine'?'low':'medium'}">${esc(r.priority)} priority</span></div><h4>${esc(r.crop)} · ${esc(r.condition)}</h4><p>${esc((r.why||[]).join(' '))}</p><small>${esc(new Date(r.createdAt).toLocaleString())}</small><button class="outline-btn" type="button" data-delete-field-inspection="${i}">Delete record</button></div>`).join('')}
$('#field-inspection-form')?.addEventListener('submit',e=>{e.preventDefault();const d=formObject(e.currentTarget),assessment=fieldPriority(d),record={...d,...assessment,id:Date.now(),createdAt:new Date().toISOString()};fieldInspections=[record,...fieldInspections].slice(0,100);localStorage.setItem(fieldInspectionKey,JSON.stringify(fieldInspections));backendPost('/api/data/fieldInspections',record);$('#field-assessment-results').innerHTML=`<div class="decision-card"><div class="decision-card-top"><span class="status-tag">${esc(d.field)} · ${esc(d.zone)}</span><span class="priority ${assessment.priority==='High'?'high':assessment.priority==='Routine'?'low':'medium'}">${assessment.priority} priority</span></div><h4>${esc(d.crop)} · inspection score ${assessment.score}</h4><ul>${assessment.why.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><p>Suggested next step: inspect several plants in this zone, compare with a healthy patch, and record dated photos. Get local expert help for severe or spreading damage.</p><p class="result-disclaimer">Rule-based triage only; score is not a disease probability.</p></div>`;renderFieldInspections();e.currentTarget.reset();toast('Field inspection saved')});
$('#field-inspection-history')?.addEventListener('click',e=>{const b=e.target.closest('[data-delete-field-inspection]');if(!b)return;fieldInspections.splice(Number(b.dataset.deleteFieldInspection),1);localStorage.setItem(fieldInspectionKey,JSON.stringify(fieldInspections));renderFieldInspections();toast('Inspection removed from this browser')});
renderFieldInspections();

$('#leaf-photo')?.addEventListener('change',async e=>{const file=e.target.files?.[0],box=$('#leaf-preview'),status=$('#photo-selection-status');if(!file){box.hidden=true;box.innerHTML='';if(status)status.textContent='No photo selected yet.';return}if(!['image/jpeg','image/png','image/webp'].includes(file.type)){toast('Choose a JPEG, PNG, or WebP image');if(status)status.textContent='Unsupported image type.';return}if(file.size>4*1024*1024){toast('Image must be smaller than 4 MB');if(status)status.textContent='Image is larger than 4 MB.';return}const url=URL.createObjectURL(file);box.hidden=false;box.innerHTML=`<img src="${url}" alt="Selected leaf photo preview"><span>Photo preview ready. AI disease prediction requires a trained model.</span>`;if(status)status.textContent='Photo selected. Saving to the local backend…';try{const dataUrl=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(new Error('Could not read image'));reader.readAsDataURL(file)});const form=$('#diagnose-form'),crop=form?.elements?.crop?.value||'',locationText=[form?.elements?.village?.value,form?.elements?.district?.value,form?.elements?.state?.value].filter(Boolean).join(', ');const result=await backendPost('/api/uploads',{dataUrl,originalName:file.name,crop,location:locationText});if(result?.ok&&result.item){if(status)status.textContent=`Photo saved to local backend (${Math.round(result.item.size/1024)} KB). File ID: ${result.item.id}`;box.insertAdjacentHTML('beforeend',`<small>Saved on this computer: <a href="${esc(result.item.url)}" target="_blank" rel="noopener noreferrer">Open saved photo</a></small>`)}else{if(status)status.textContent='Preview ready; local backend not connected, so the photo was not stored on the server.'}}catch(err){if(status)status.textContent='Preview ready; upload failed. Start the app using npm start to enable local storage.'}});

$('#voice-input')?.addEventListener('click',()=>{const SpeechRecognition=window.SpeechRecognition||window.webkitSpeechRecognition;if(!SpeechRecognition){toast('Voice input is not supported in this browser. Try Chrome.');return}const recognition=new SpeechRecognition();recognition.lang='hi-IN';recognition.interimResults=false;recognition.maxAlternatives=1;recognition.onstart=()=>toast('Listening… Hindi or English');recognition.onresult=event=>{$('#chat-input').value=event.results[0][0].transcript;$('#chat-input').focus()};recognition.onerror=()=>toast('Could not hear clearly. Please try again.');recognition.start()});

// Voice output is opt-in and uses the browser's speech synthesis when available.
const voiceToggle=document.createElement('button');voiceToggle.type='button';voiceToggle.className='voice-output-btn';voiceToggle.textContent='🔊 Speak latest answer';voiceToggle.addEventListener('click',()=>{if(!('speechSynthesis' in window)){toast('Voice output is not supported in this browser');return}const bubbles=$$('#chat-messages .chat-bubble.bot');const last=bubbles[bubbles.length-1];if(!last){toast('Ask a question first');return}const utterance=new SpeechSynthesisUtterance(last.childNodes[0]?.textContent||last.textContent);utterance.lang=/[\u0900-\u097F]/.test(utterance.text)?'hi-IN':'en-IN';speechSynthesis.cancel();speechSynthesis.speak(utterance)});$('.chat-layout')?.appendChild(voiceToggle);


// Google Maps agricultural shop finder. Results open Google Maps, which supplies live business listings.
const shopCategories = {
  seed: {label:'Seed shops', query:'seed store'},
  fertilizer: {label:'Fertilizer and nutrient shops', query:'fertilizer shop'},
  pesticide: {label:'Crop protection shops', query:'agricultural pesticide shop'},
  equipment: {label:'Agricultural equipment and machinery', query:'agricultural equipment dealer'},
  irrigation: {label:'Irrigation and pump suppliers', query:'drip irrigation supplier water pump shop'},
  soil: {label:'Soil testing laboratories', query:'soil testing laboratory agriculture'},
  nursery: {label:'Plant nurseries', query:'plant nursery'},
  expert: {label:'KVK / agriculture office / crop experts', query:'Krishi Vigyan Kendra agriculture office'},
  all: {label:'All agricultural shops and services', query:'agricultural supplies seed fertilizer farm equipment soil testing'}
};
function mapsSearchUrl(query, location) {
  const url = new URL('https://www.google.com/maps/search/');
  url.searchParams.set('api', '1');
  url.searchParams.set('query', `${query} near ${location}`);
  return url.toString();
}
function mapsDirectionsUrl(location) {
  const url = new URL('https://www.google.com/maps/dir/');
  url.searchParams.set('api', '1');
  url.searchParams.set('destination', location);
  url.searchParams.set('travelmode', 'driving');
  return url.toString();
}
$('#shop-finder-form')?.addEventListener('submit', e => {
  e.preventDefault();
  const d = formObject(e.currentTarget);
  const location = [d.village.trim(), d.district.trim(), d.state.trim(), 'India'].filter(Boolean).join(', ');
  const selected = d.need === 'all' ? Object.entries(shopCategories) : [[d.need, shopCategories[d.need]]];
  const categories = selected.filter(([key]) => key !== 'all');
  const list = d.need === 'all' ? [['all', shopCategories.all], ...categories] : selected;
  $('#shop-finder-message').textContent = `Searching Google Maps for ${d.crop} farming needs near ${location}.`;
  $('#shop-results').classList.remove('empty-state');
  $('#shop-results').innerHTML = `<div class="shop-location-summary"><span class="shop-pin">⌖</span><div><b>${esc(location)}</b><small>Crop: ${esc(d.crop)} · Select a category to view current Google Maps listings.</small></div><a class="outline-btn shop-directions" href="${mapsDirectionsUrl(location)}" target="_blank" rel="noopener noreferrer">Open directions ↗</a></div><div class="shop-category-grid">${list.map(([key, item]) => `<article class="shop-category-card"><span class="shop-category-icon">${key==='seed'?'🌱':key==='fertilizer'?'🧪':key==='pesticide'?'🛡️':key==='equipment'?'🚜':key==='irrigation'?'💧':key==='soil'?'🧫':key==='nursery'?'🌿':key==='expert'?'👩‍🌾':'📍'}</span><div class="shop-category-copy"><b>${esc(item.label)}</b><small>Search ${esc(item.query)} around the selected location</small></div><a href="${mapsSearchUrl(item.query, location)}" target="_blank" rel="noopener noreferrer">View shops on Maps ↗</a></article>`).join('')}</div><p class="shop-results-note">Tip: In Google Maps, compare distance, recent reviews, opening hours and call the shop to confirm stock before travelling.</p>`;
});


// Added farmer support modules. These are transparent local tools, not trained AI predictions.
const recoveryKey='agri-recovery-v1', calendarKey='agri-calendar-v1';
let recoveryLogs=read(recoveryKey,[]), calendarTasks=read(calendarKey,[]);
function persistList(key,items){localStorage.setItem(key,JSON.stringify(items));const collection=({[recoveryKey]:'recovery',[calendarKey]:'calendar'})[key];if(collection)backendPut(`/api/data/${collection}/replace`,{items}).catch(()=>{});}
function renderRecovery(){const host=$('#recovery-results');if(!host)return;if(!recoveryLogs.length){host.innerHTML='<div class="empty-state"><b>No follow-ups yet</b><p>Saved entries will appear here on this device.</p></div>';return}host.innerHTML=recoveryLogs.map((r,i)=>`<div class="decision-card"><div class="decision-card-top"><span class="status-tag">${esc(r.crop)}</span><span class="priority ${r.condition==='worse'?'high':r.condition==='improving'?'low':'medium'}">${esc(({improving:'Improving',same:'No clear change',worse:'Worse',uncertain:'Uncertain'})[r.condition]||r.condition)}</span></div><h4>${esc(r.action)}</h4><p>${esc(r.notes||'No extra notes entered.')}</p><small>${esc(r.date)}</small><div style="margin-top:10px"><button class="outline-btn" type="button" data-recovery-delete="${i}">Delete entry</button></div></div>`).join('')}
$('#recovery-form')?.addEventListener('submit',e=>{e.preventDefault();const d=formObject(e.currentTarget);recoveryLogs.unshift({...d,date:new Date().toLocaleString('en-IN')});recoveryLogs=recoveryLogs.slice(0,100);persistList(recoveryKey,recoveryLogs);renderRecovery();e.currentTarget.reset();toast('Follow-up saved')});
$('#recovery-results')?.addEventListener('click',e=>{const b=e.target.closest('[data-recovery-delete]');if(!b)return;recoveryLogs.splice(Number(b.dataset.recoveryDelete),1);persistList(recoveryKey,recoveryLogs);renderRecovery()});
$('#clear-recovery')?.addEventListener('click',()=>{if(!recoveryLogs.length)return;recoveryLogs=[];persistList(recoveryKey,recoveryLogs);renderRecovery();toast('Recovery history cleared')});
$('#soil-form')?.addEventListener('submit',e=>{e.preventDefault();const d=formObject(e.currentTarget),ph=d.ph===''?null:Number(d.ph),items=[];if(ph===null)items.push(['Soil pH not entered','If possible, arrange a lab soil test; do not infer pH from leaf colour.']);else if(ph<5.5)items.push(['Acidic soil reading','Ask a soil-testing lab or local agronomist whether crop-specific pH correction is appropriate; do not apply lime without a recommendation.']);else if(ph>8)items.push(['Alkaline soil reading','Ask for a soil test that checks salinity and nutrient availability; do not apply amendments without test-based advice.']);else items.push(['pH reading in a broadly common crop range','Suitability depends on the specific crop, soil type and local conditions; compare with crop-specific recommendations.']);if(d.moisture==='dry')items.push(['Dry soil reported','Check moisture at root depth and recent irrigation/rain before deciding whether to water.']);if(d.moisture==='wet')items.push(['Wet soil reported','Inspect for standing water and drainage problems; avoid adding water until field conditions are checked.']);if(d.symptom==='yellow')items.push(['Yellowing observed','Possible causes include nutrient issues, water stress, root problems or disease. Check symptom pattern and obtain soil/plant diagnosis before fertilizing.']);if(d.symptom==='stunted')items.push(['Slow growth observed','Record crop stage, spacing, moisture, roots and recent inputs; a soil test can help narrow nutrient causes.']);if(d.symptom==='burn')items.push(['Leaf edge burn observed','Check water stress, salinity, spray history and nutrient status; the symptom alone is not diagnostic.']);if(d.test==='no')items.push(['Recommended next step: soil lab test','Ask for crop-relevant pH, electrical conductivity and nutrient analysis through a recognised local soil-testing service.']);$('#soil-results').innerHTML=`<div class="result-stack">${items.map((x,i)=>`<div class="decision-card"><div class="decision-card-top"><span class="finding-number">0${i+1}</span><span class="confidence">Check</span></div><h4>${esc(x[0])}</h4><p>${esc(x[1])}</p></div>`).join('')}<p class="result-disclaimer">These are general checks, not a diagnosis or fertilizer dose. Use a verified soil report and local crop guidance.</p></div>`;const record={...d,ph,findings:items.map(x=>({title:x[0],guidance:x[1]})),createdAt:new Date().toISOString()};let soilHistory=read('agri-soil-checks-v1',[]);soilHistory=[record,...soilHistory].slice(0,100);localStorage.setItem('agri-soil-checks-v1',JSON.stringify(soilHistory));backendPost('/api/data/soilChecks',record);toast('Soil checklist prepared and saved')});
$('#yield-form')?.addEventListener('submit',e=>{e.preventDefault();const d=formObject(e.currentTarget),area=Number(d.area),base=Number(d.yield),price=Number(d.price),cost=Number(d.cost),factor={low:[.95,1.05],medium:[.85,1.10],high:[.70,1.05]}[d.risk]||[.85,1.1];const rows=[['Lower scenario',base*factor[0]],['Baseline',base],['Upper scenario',base*factor[1]]];$('#yield-results').innerHTML=`<div class="impact-metrics">${rows.map(r=>{const production=r[1]*area,revenue=production*price,net=revenue-cost;return `<div class="${net>=0?'positive':'negative'}"><small>${esc(r[0])} · ${esc(d.crop)}</small><b>${production.toFixed(1)} q</b><small>Gross ₹${Math.round(revenue).toLocaleString('en-IN')}</small><small>Net after entered cost ₹${Math.round(net).toLocaleString('en-IN')}</small></div>`}).join('')}</div><p class="result-disclaimer">Scenario bounds are assumptions selected by the app, not calibrated probabilities. Price, yield and cost are your inputs; this is not a trained yield forecast.</p>`;toast('Scenarios calculated')});
function renderCalendar(){const host=$('#calendar-results');if(!host)return;if(!calendarTasks.length){host.innerHTML='<div class="empty-state"><b>No tasks scheduled</b><p>Add a task to get started.</p></div>';return}calendarTasks.sort((a,b)=>a.date.localeCompare(b.date));host.innerHTML=calendarTasks.map((t,i)=>`<div class="decision-card"><div class="decision-card-top"><span class="status-tag">${esc(t.crop)}</span><span class="priority ${t.priority.toLowerCase()}">${esc(t.priority)}</span></div><h4>${esc(t.task)}</h4><p>Due: <b>${esc(t.date)}</b></p><div style="display:flex;gap:8px;flex-wrap:wrap"><button class="outline-btn" type="button" data-task-done="${i}">Mark complete</button><button class="outline-btn" type="button" data-task-delete="${i}">Delete</button></div></div>`).join('')}
$('#calendar-form')?.addEventListener('submit',e=>{e.preventDefault();const d=formObject(e.currentTarget);calendarTasks.push({...d,done:false,id:Date.now()});persistList(calendarKey,calendarTasks);renderCalendar();e.currentTarget.reset();$('#calendar-form [name="date"]').value=new Date().toISOString().slice(0,10);toast('Task added')});
$('#calendar-results')?.addEventListener('click',e=>{const done=e.target.closest('[data-task-done]'),del=e.target.closest('[data-task-delete]');if(done){const i=Number(done.dataset.taskDone);calendarTasks[i].done=true;calendarTasks[i].priority='Low';calendarTasks[i].task+=' ✓ Completed';persistList(calendarKey,calendarTasks);renderCalendar();toast('Task marked complete')}else if(del){calendarTasks.splice(Number(del.dataset.taskDelete),1);persistList(calendarKey,calendarTasks);renderCalendar()}});
function mapSearch(q){return 'https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(q)}
// Personalized farm roadmap: rule-based matching of official scheme information to the farmer's entered profile.
const farmSchemeCatalog = [
 {id:'pmkisan',title:'PM-KISAN income support',need:['general','income'],why:f=>f.land_status==='owner'?'Your profile says you are a recorded landholder; check the scheme’s current eligibility rules and exclusions.':'Land records/tenancy status may affect eligibility. Ask the district agriculture office how your situation is treated.',url:'https://pmkisan.gov.in/',action:'Check eligibility and beneficiary status; complete the official registration/eKYC steps only if eligible.',docs:'Land/record details, identity and bank details may be requested on the official portal; requirements can vary.',steps:['Open the official PM-KISAN portal and read current eligibility/exclusion rules.','Check beneficiary or self-registration status, if applicable.','If records need correction, contact the state/block agriculture office or official helpdesk.','Save the application/reference number and track status on the official portal.']},
 {id:'pmfby',title:'Pradhan Mantri Fasal Bima Yojana (crop insurance)',need:['general','insurance'],why:f=>`For ${f.crop||'your crop'}, verify whether the crop and area are notified for your district and season and whether enrolment is open.`,url:'https://pmfby.gov.in/',action:'Check notified crop, district, season, enrolment window, premium and claim/reporting rules.',docs:'Crop/land records, bank and identity details, sowing/insured-area information and loss evidence may be required depending on case.',steps:['Open the official PMFBY portal and select the farmer/enrolment or claim section.','Confirm your district, crop and season are covered and check the deadline.','Apply through the listed official channel if eligible; keep receipt/policy details.','For crop loss, follow official reporting timelines and keep dated photos and records.']},
 {id:'soil',title:'Soil Health Card / soil testing',need:['general','soil'],why:f=>f.soil_ph===null||f.soil_ph===undefined?'No soil pH was entered, so a verified soil test can help establish a baseline.':`Your entered soil pH is ${f.soil_ph}; a lab report can verify pH and nutrient status before input decisions.`,url:'https://soilhealth.dac.gov.in/',action:'Find a recognised soil-testing route and request a soil report for your crop and plot.',docs:'Farm/plot location and land details; the local soil-testing office will confirm the exact requirements.',steps:['Open the official Soil Health Card portal or contact the block/district agriculture office.','Ask whether soil sample collection or a soil-testing lab is available for your village.','Follow the lab’s sample-collection instructions and retain the sample receipt.','Use the official report for crop-specific nutrient advice; do not guess fertilizer doses from leaf colour alone.']},
 {id:'irrigation',title:'Micro-irrigation / water-saving support',need:['general','irrigation'],why:f=>`Your selected irrigation source is ${f.irrigation||'not specified'}. Ask the state department whether drip/sprinkler assistance applies to your crop and area.`,url:'https://pmksy.gov.in/',action:'Check current state component, approved equipment, farmer contribution and pre-approval rules before purchasing equipment.',docs:'Land/plot details, crop/area information, identity and bank details may be required by the state application.',steps:['Open the official PMKSY information portal and locate the current state implementation route.','Contact the district horticulture/agriculture office to confirm current subsidy windows and approved vendors.','Get written confirmation of eligibility and whether approval is required before purchase.','Submit the state-required application and keep the acknowledgement and invoice records.']},
 {id:'machinery',title:'Farm machinery / mechanisation assistance',need:['general','machinery'],why:f=>`For a ${f.area_acres||'specified'}-acre farm, check whether a state or central mechanisation component fits your equipment need and farmer category.`,url:'https://agrimachinery.nic.in/',action:'Check the current scheme, equipment list, application dates and whether purchase must wait for approval.',docs:'Farm and land details, selected equipment quotation, identity/bank documents and category certificate if applicable.',steps:['Open the official farm mechanisation portal and review current notices.','Confirm with the district agriculture office which component is active in your state.','Check approved equipment/vendors and the application timeline before paying a dealer.','Apply through the notified process and keep the application number and purchase documents.']},
 {id:'myscheme',title:'Find other central and state schemes',need:['general','income','insurance','soil','irrigation','machinery','training'],why:f=>`Use your state (${f.state||'not entered'}), district (${f.district||'not entered'}), crop (${f.crop||'not entered'}) and farmer category to look for additional schemes.`,url:'https://www.myscheme.gov.in/',action:'Search and compare official scheme eligibility, benefits, documents and application channels.',docs:'Prepare only the documents named on the specific official scheme page; do not upload sensitive documents to unknown websites.',steps:['Search by farmer/agriculture, your state and the need you selected.','Open the scheme’s official details and read eligibility, exclusions, benefit, deadline and documents.','Confirm any district-specific notification with the state/block agriculture office.','Apply through the official portal or authorised office and save the acknowledgement.']}
];
function officialStateSearch(f){const q=`site:gov.in ${f.state||''} agriculture department farmer schemes ${f.district||''} ${f.crop||''}`;return 'https://www.google.com/search?q='+encodeURIComponent(q)}
function renderFarmPersonalPlan(){const host=$('#farm-personal-plan'),selector=$('#farm-plan-select');if(!host)return;farms=read('agri-farms',seed);if(!farms.length){host.innerHTML='<div class="empty-state"><b>Add a farm to build your roadmap</b><p>Enter the state, district, crop and farm details first.</p></div>';return}let f=farms.find(x=>String(x.id)===String(selector?.value))||farms[farms.length-1];if(selector&&String(selector.value)!==String(f.id))selector.value=String(f.id);const need=f.scheme_need||'general';let list=farmSchemeCatalog.filter(s=>s.need.includes(need));if(need!=='general')list=[...list,...farmSchemeCatalog.filter(s=>s.need.includes('general')&&!list.some(x=>x.id===s.id))];const location=farmLocation(f);const mapUrl='https://www.google.com/maps/search/?api=1&query='+encodeURIComponent('District Agriculture Office Krishi Vigyan Kendra '+location);const cards=list.map((s,i)=>`<article class="farm-scheme-card"><div class="farm-scheme-top"><span class="status-tag">${i===0?'PRIORITY TO CHECK':'POSSIBLE MATCH'}</span><span class="scheme-number">0${i+1}</span></div><h4>${esc(s.title)}</h4><p>${esc(s.why(f))}</p><div class="farm-scheme-action"><b>What to do</b><p>${esc(s.action)}</p></div><details><summary>Documents to prepare</summary><p>${esc(s.docs)}</p></details><details><summary>Application roadmap</summary><ol>${s.steps.map(step=>`<li>${esc(step)}</li>`).join('')}</ol></details><div class="farm-scheme-links"><a class="outline-btn" href="${s.url}" target="_blank" rel="noopener noreferrer">Official portal ↗</a><a class="text-btn" href="${officialStateSearch(f)}" target="_blank" rel="noopener noreferrer">Check state updates ↗</a></div></article>`).join('');const profileBits=[f.crop,`${f.area_acres} acres`,f.land_status==='owner'?'Recorded landholder':f.land_status==='tenant'?'Tenant / lease':'Sharecropper / other',f.irrigation||'Irrigation not entered'].filter(Boolean);host.innerHTML=`<div class="farm-profile-summary"><div><span class="welcome-kicker">PERSONALIZED FOR</span><h4>${esc(f.name)}</h4><p>⌖ ${esc(location)}</p><div class="farm-meta">${profileBits.map(x=>`<span>${esc(x)}</span>`).join('')}</div></div><a class="outline-btn" href="${mapUrl}" target="_blank" rel="noopener noreferrer">Find district agriculture office ↗</a></div><section class="farm-map-panel"><div class="farm-map-copy"><span class="welcome-kicker">LOCAL AGRICULTURAL SUPPORT</span><h4>Google Maps for ${esc(f.district||f.state||'your district')}</h4><p>Explore Krishi Vigyan Kendras (KVKs), District Agriculture Offices and agricultural advisory centres for crop diagnosis, soil testing guidance and official support.</p><div class="farm-map-actions"><a class="primary-btn" href="${mapUrl}" target="_blank" rel="noopener noreferrer">Open results in Google Maps ↗</a><a class="outline-btn" href="https://www.google.com/maps/search/?api=1&query=${encodeURIComponent('Krishi Vigyan Kendra '+location)}" target="_blank" rel="noopener noreferrer">Find nearby KVKs ↗</a></div><small>Google Maps listings can show available address, phone, hours, reviews and directions. Confirm details with the centre before travelling.</small></div><iframe class="farm-google-map" title="Google Maps agricultural support centres near ${esc(location)}" src="https://maps.google.com/maps?q=${encodeURIComponent('Krishi Vigyan Kendra District Agriculture Office '+location)}&output=embed" loading="lazy" referrerpolicy="no-referrer-when-downgrade" allowfullscreen></iframe></section><div class="scheme-match-note"><b>How these matches work:</b> recommendations are filtered from the farm profile and are not a government eligibility decision. Check current district notifications, deadlines and documents with the official portal/office.</div><div class="farm-scheme-grid">${cards}</div><div class="farm-roadmap-footer"><h4>Your benefit application checklist</h4><ol><li>Choose a scheme and confirm eligibility, active dates and district/crop coverage from the official source.</li><li>Collect only the documents required by that scheme; never share OTPs or pay an unofficial agent.</li><li>Apply on the official portal or at the authorised agriculture office/CSC, as the scheme instructs.</li><li>Save the acknowledgement/application number and track status; ask the office about grievance steps if delayed or rejected.</li></ol><p>Useful official directories: <a href="https://www.myscheme.gov.in/" target="_blank" rel="noopener noreferrer">MyScheme</a> · <a href="https://agriwelfare.gov.in/" target="_blank" rel="noopener noreferrer">Agriculture & Farmers Welfare</a> · <a href="https://soilhealth.dac.gov.in/" target="_blank" rel="noopener noreferrer">Soil Health Card</a>.</p></div>`}
$('#farm-plan-select')?.addEventListener('change',renderFarmPersonalPlan);
$('#farms-list')?.addEventListener('click',e=>{const b=e.target.closest('[data-farm-plan-id]');if(!b)return;go('farms');if($('#farm-plan-select'))$('#farm-plan-select').value=b.dataset.farmPlanId;renderFarmPersonalPlan();$('#farm-personal-plan')?.scrollIntoView({behavior:'smooth',block:'start'})});

$('#scheme-form')?.addEventListener('submit',e=>{e.preventDefault();const d=formObject(e.currentTarget),loc=`${d.village}, ${d.district}, ${d.state}, India`;const mapsNeed={kvk:'Krishi Vigyan Kendra agriculture office',soil:'soil testing laboratory',insurance:'crop insurance help centre',income:'government agriculture office farmer income support',machinery:'agricultural machinery custom hiring centre'}[d.need];const official=[['PM-KISAN official portal','https://pmkisan.gov.in/'],['Pradhan Mantri Fasal Bima Yojana','https://pmfby.gov.in/'],['Soil Health Card portal','https://soilhealth.dac.gov.in/'],['Agriculture Ministry portal','https://agriwelfare.gov.in/'],['Farm mechanisation portal','https://agrimachinery.nic.in/']];$('#scheme-results').innerHTML=`<div class="shop-location-summary"><span class="shop-pin">⌖</span><div><b>${esc(loc)}</b><small>Local search links; check current availability and eligibility with the office.</small></div><a class="outline-btn shop-directions" target="_blank" rel="noopener noreferrer" href="${mapSearch(mapsNeed+' near '+loc)}">Search nearby help ↗</a></div><div class="shop-category-grid">${official.map(o=>`<div class="shop-category-card"><span class="shop-category-icon">↗</span><div class="shop-category-copy"><b>${esc(o[0])}</b><small>Official information portal; scheme rules and eligibility may change.</small></div><a href="${o[1]}" target="_blank" rel="noopener noreferrer">Open official site ↗</a></div>`).join('')}</div><p class="shop-results-note">The Maps link is a location-based search, not a verified nearest-office result. Scheme links do not confirm your eligibility. Do not share OTPs or pay unofficial agents.</p>`;toast('Resources ready')});
// Refresh the newly added local modules whenever opened.
const originalGoWithModules=go;
go=function(view){originalGoWithModules(view);if(view==='recovery')renderRecovery();if(view==='calendar')renderCalendar()};
$('#calendar-form [name="date"]')?.setAttribute('value',new Date().toISOString().slice(0,10));

// Browser-only prototype authentication. For production, use a trusted auth provider and server-side sessions.
const authUsersKey='agropilot-demo-users-v1', authSessionKey='agropilot-demo-session-v1';
function authUsers(){return read(authUsersKey,[])}
function showAuthPane(pane){const signup=pane==='signup';$('#login-pane').hidden=signup;$('#signup-pane').hidden=!signup;$$('[data-auth-tab]').forEach(b=>b.classList.toggle('active',b.dataset.authTab===pane));$('#login-message').textContent='';$('#signup-message').textContent='';$('#login-message').classList.remove('success');$('#signup-message').classList.remove('success')}
function showWorkspace(user){$('#auth-screen').hidden=true;$('#app-shell').classList.add('authenticated');$('#signed-in-name').textContent=user.name||user.email;$('#signed-in-name').title=user.email;$('#user-avatar').textContent=(user.name||user.email).trim().split(/\s+/).slice(0,2).map(x=>x[0]).join('').toUpperCase();}
function showLogin(){sessionStorage.removeItem(authSessionKey);$('#app-shell').classList.remove('authenticated');$('#auth-screen').hidden=false;showAuthPane('login')}
async function passwordDigest(password){if(!window.crypto?.subtle)throw new Error('Secure password hashing is not available in this browser. Open the project using VS Code Live Server or a modern browser.');const bytes=new TextEncoder().encode(password);const hash=await crypto.subtle.digest('SHA-256',bytes);return [...new Uint8Array(hash)].map(b=>b.toString(16).padStart(2,'0')).join('')}
$$('[data-auth-tab]').forEach(b=>b.addEventListener('click',()=>showAuthPane(b.dataset.authTab)));
$('#signup-form')?.addEventListener('submit',async e=>{e.preventDefault();const d=formObject(e.currentTarget),msg=$('#signup-message');msg.classList.remove('success');msg.textContent='';const email=d.email.trim().toLowerCase();if(d.password!==d.confirm){msg.textContent='Passwords do not match. Please try again.';return}if(d.password.length<6){msg.textContent='Use at least 6 characters for this prototype.';return}if(authUsers().some(u=>u.email===email)){msg.textContent='An account with this email already exists. Please log in.';return}try{const user={name:d.name.trim(),email,passwordHash:await passwordDigest(d.password)};localStorage.setItem(authUsersKey,JSON.stringify([...authUsers(),user]));sessionStorage.setItem(authSessionKey,JSON.stringify({name:user.name,email:user.email}));showWorkspace(user);toast('Account created successfully')}catch(err){msg.textContent=err.message||'Could not create account. Please try again.'}});
$('#login-form')?.addEventListener('submit',async e=>{e.preventDefault();const d=formObject(e.currentTarget),msg=$('#login-message');msg.classList.remove('success');msg.textContent='';try{const email=d.email.trim().toLowerCase(),digest=await passwordDigest(d.password),user=authUsers().find(u=>u.email===email&&u.passwordHash===digest);if(!user){msg.textContent='Incorrect email or password. If you are new, create an account first.';return}sessionStorage.setItem(authSessionKey,JSON.stringify({name:user.name,email:user.email}));showWorkspace(user);toast('Logged in successfully')}catch(err){msg.textContent=err.message||'Could not log in. Please try again.'}});
$('#logout-btn')?.addEventListener('click',()=>{showLogin();$('#login-form')?.reset();toast('You have logged out')});
try{const active=JSON.parse(sessionStorage.getItem(authSessionKey)||'null');if(active?.email&&authUsers().some(u=>u.email===active.email))showWorkspace(active);else showLogin()}catch{showLogin()}

