// Market rate lookup: route farmers to official sources with their selected crop and location.
$('#market-search-form')?.addEventListener('submit',e=>{
  e.preventDefault();
  const d=formObject(e.currentTarget);
  const query=`${d.crop} mandi price ${d.district} ${d.state} India`;
  const links=[
    {name:'Agmarknet — official market information',url:'https://agmarknet.gov.in/'},
    {name:'e-NAM — National Agriculture Market',url:'https://enam.gov.in/'},
    {name:'Search this crop and district',url:'https://www.google.com/search?q='+encodeURIComponent(query)}
  ];
  $('#market-live-links').innerHTML=links.map(x=>`<div class="shop-category-card"><span class="shop-category-icon">↗</span><div class="shop-category-copy"><b>${esc(x.name)}</b><small>${esc(query)}</small></div><a href="${x.url}" target="_blank" rel="noopener noreferrer">Open ↗</a></div>`).join('');
  toast('Official rate-search links prepared');
});
